\title{The Co-index of Free $\Ztwo$-Complexes under Suspension:\\
A Constructive Foundation for Sharp Excess}
\author{Aristotle}
\date{2026-07-13}

\begin{document}

\begin{abstract}
The \emph{co-index} of a free $\Ztwo$-space measures the largest dimension $n$ for
which the $n$-sphere admits an antipode-preserving map into the space. It is the
combinatorial engine behind the Borsuk--Ulam theorem and Lov\'asz-type chromatic lower
bounds. A guiding question, in the Simonyi--Tardos--Vr\'ecica circle of problems, asks
how the co-index behaves under the unreduced suspension $S(K) = K * S^0$, where the
sharp upper bound $\coind(S(K)) \le \dim(K) + 1$ is conjectured to be attained with
maximal excess $d - c$ for \emph{every} feasible starting co-index $1 \le c \le d$ of a
$d$-dimensional complex. We develop a self-contained, subdivision-free combinatorial
theory of free $\Ztwo$-simplicial complexes, their equivariant simplicial maps, the
octahedral spheres $\Oct n$ (triangulations of $S^n$), and the join-with-$S^0$
suspension. Within this framework we establish the constructive lower-bound half of the
maximal-excess program unconditionally: (i) suspension is functorial; (ii) there is an
explicit equivariant simplicial map $\Oct(n+1) \to S(\Oct n)$ realizing the classical
homeomorphism $S^{n+1} \cong S(S^n)$; (iii) consequently suspension raises the co-index
by at least one; and (iv) the octahedral tower realizes the diagonal
$\coind(\Oct n) = n$. We also prove a genuine combinatorial Borsuk--Ulam instance --- its
base case --- showing there is no equivariant simplicial map $\Oct n \to \Oct 0$ for
$n \ge 1$, so the co-index of $S^0$ is exactly $0$. Together these results provide the
verified scaffolding on which the large-jump construction of the sharp-excess conjecture
can be built, and they isolate precisely why that construction is deeper.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Co-index and its role}
Let $X$ be a topological space with a free involution $\nu : X \to X$ (so
$\nu\circ\nu = \mathrm{id}$ and $\nu(x) \ne x$ for all $x$); such a pair is a
\emph{free $\Ztwo$-space}. The $n$-sphere $S^n$ with the antipodal map is the model
example. A map $f : X \to Y$ of free $\Ztwo$-spaces is \emph{equivariant} if it commutes
with the involutions. The \emph{co-index} is
\[
  \coind(X) = \max\{ n : \text{there is an equivariant map } S^n \to X \},
\]
the largest sphere mapping antipodally into $X$. The Borsuk--Ulam theorem is the
inequality $\coind(X) \le \mathrm{index}(X)$; its classical form is
$\coind(S^n) = n$. These invariants underlie the topological method in combinatorics:
for a graph $G$ one has $\chi(G) \ge \coind(B(G)) + 2$, where $B(G)$ is the box complex.

\subsection{Suspension and the sharp-excess question}
The \emph{unreduced suspension} of a free $\Ztwo$-space $K$ is the join $S(K) = K * S^0$:
two antipodal apexes are adjoined and joined to every point of $K$. Topologically
$S(S^n) \cong S^{n+1}$. For a $d$-dimensional complex there is a sharp upper bound
$\coind(S(K)) \le \dim(K) + 1 = d + 1$, conjectured to be attained with maximal excess.

\begin{conjecture}[Sharp Excess]
For all integers $d \ge 2$ and $c$ with $1 \le c \le d$, there is a finite free
$\Ztwo$-complex $K$ of dimension $d$ with $\coind(K) = c$ and $\coind(S(K)) = d+1$,
achieving the maximal excess $d - c$.
\end{conjecture}

The case $c = 1$ is known; the general statement is open. This paper establishes the
constructive lower-bound half and the Borsuk--Ulam base case.

\section{The combinatorial model}

\begin{definition}[Free $\Ztwo$-complex]
A \emph{free $\Ztwo$-complex} on a vertex set $V$ consists of an involution
$\alpha : V \to V$ that is \emph{free} ($\alpha(v) \ne v$ for all $v$), together with a
family of faces $\FF \subseteq 2^V$ that is downward closed, contains $\emptyset$, and is
$\alpha$-invariant ($s \in \FF \Rightarrow \alpha(s) \in \FF$). Its dimension is
$\max\{|s|-1 : s \in \FF\}$.
\end{definition}

\begin{definition}[$\Ztwo$-simplicial map]
For free $\Ztwo$-complexes $K$ on $V$ and $L$ on $W$, a \emph{$\Ztwo$-simplicial map}
$f : K \to L$ is a vertex map $f : V \to W$ that is equivariant,
$f(\alpha_K(v)) = \alpha_L(f(v))$, and simplicial,
$s \in \FF_K \Rightarrow f(s) \in \FF_L$.
\end{definition}

\begin{definition}[Co-index lower bound]
For a fixed triangulated $n$-sphere $\Oct n$ (below) and a free $\Ztwo$-complex $K$,
write $\Oct n \Cimp K$ for the existence of a $\Ztwo$-simplicial map
$\Oct n \to K$. This is a subdivision-free lower bound for the topological co-index.
\end{definition}

\section{The category of free $\Ztwo$-complexes}

\begin{proposition}[Identity]
For any free $\Ztwo$-complex $K$, the identity vertex map is a $\Ztwo$-simplicial map
$K \to K$.
\end{proposition}

\begin{proof}
The identity commutes with $\alpha_K$ and sends each face to itself.
\end{proof}

\begin{proposition}[Composition]
If $g : K \to L$ and $h : L \to M$ are $\Ztwo$-simplicial maps, so is
$h \circ g : K \to M$.
\end{proposition}

\begin{proof}
Equivariance: $h(g(\alpha_K v)) = h(\alpha_L(g v)) = \alpha_M(h(g v))$. Simpliciality:
$(h\circ g)(s) = h(g(s))$; $g(s) \in \FF_L$ and hence $h(g(s)) \in \FF_M$.
\end{proof}

\section{The octahedral spheres $\Oct n \cong S^n$}

\begin{definition}[Octahedral $n$-sphere]
$\Oct n$ is the boundary complex of the $(n+1)$-cross-polytope. Vertices are
$\{0,\dots,n\}\times\{+,-\}$; the involution flips the sign,
$\alpha(i,\varepsilon) = (i,-\varepsilon)$; a finite vertex set is a face iff it contains
no antipodal pair (for no axis $i$ are both $(i,+)$ and $(i,-)$ present).
\end{definition}

The involution is free, and the faces are downward closed, contain $\emptyset$, and are
$\alpha$-invariant. Realizing $(i,\pm)$ as $\pm e_i \in \mathbb{R}^{n+1}$ exhibits
$\Oct n$ as a triangulation of $S^n$.

\begin{lemma}[Top face]
$\{(i,+) : 0 \le i \le n\}$ is a face of $\Oct n$ with $n+1$ vertices.
\end{lemma}

\begin{proof}
It contains no $-$ vertex, hence no antipodal pair.
\end{proof}

\begin{lemma}[Dimension bound]
Every face $s$ of $\Oct n$ satisfies $|s| \le n+1$; hence $\dim(\Oct n) = n$.
\end{lemma}

\begin{proof}
The no-antipodal-pair condition makes the axis-projection $(i,\varepsilon)\mapsto i$
injective on any face $s$, so $|s| \le n+1$. With the top face, the dimension is $n$.
\end{proof}

\begin{corollary}
$\Oct n \Cimp \Oct n$ holds via the identity: $\coind(\Oct n) \ge n$.
\end{corollary}

\section{The suspension $S(K) = K * S^0$}

\begin{definition}[Suspension]
For a free $\Ztwo$-complex $K$ on $V$, $S(K)$ is defined on $V \sqcup \{N,S\}$. The
involution acts as $\alpha_K$ on the base and swaps $N \leftrightarrow S$. A set $T$ is a
face iff its base part $T \cap V$ is a face of $K$ and $T$ does not contain both apexes.
\end{definition}

The apex-exclusion makes $\{N,S\}$ behave as $S^0$. The face family is downward closed,
contains $\emptyset$, and is $\alpha_{S(K)}$-invariant.

\begin{proposition}[Functoriality]
A $\Ztwo$-simplicial map $g : K \to L$ induces $S(g) : S(K) \to S(L)$ acting as $g$ on
the base and as the identity on apexes.
\end{proposition}

\begin{proof}
Equivariance holds on base and apexes. For a face $T$ of $S(K)$, the base part maps to a
face of $L$; $S(g)$ fixes apexes, so if $T$ omits an apex so does $S(g)(T)$.
\end{proof}

\begin{lemma}[Dimension raise]
If $s$ is a face of $K$ then $\{N\}\cup s$ is a face of $S(K)$ with $|s|+1$ vertices;
hence $\dim(S(K)) = \dim(K)+1$.
\end{lemma}

\section{The combinatorial homeomorphism and the co-index inequality}

\begin{definition}[Connecting map]
Define $\varphi_n : \Oct(n+1) \to S(\Oct n)$ on vertices by
\[
  \varphi_n(i,\varepsilon) =
  \begin{cases}
    (i,\varepsilon)\ \text{in the base}, & 0 \le i \le n,\\
    N, & i = n+1,\ \varepsilon = +,\\
    S, & i = n+1,\ \varepsilon = -.
  \end{cases}
\]
\end{definition}

\begin{lemma}
$\varphi_n$ is equivariant.
\end{lemma}

\begin{proof}
For $i \le n$ both sides flip the sign in the base; for $i = n+1$ flipping the sign swaps
$N \leftrightarrow S$, the apex swap.
\end{proof}

\begin{lemma}
$\varphi_n$ is simplicial.
\end{lemma}

\begin{proof}
The base part of $\varphi_n(s)$ avoids antipodal pairs since $s$ does. Both apexes
appearing would require the antipodal pair $(n+1,\pm)$ in $s$, forbidden. Hence
$\varphi_n(s)$ contains at most one apex and a base face.
\end{proof}

\begin{theorem}[Combinatorial $S^{n+1} \cong S(S^n)$]
$\varphi_n$ is a $\Ztwo$-simplicial map $\Oct(n+1) \to S(\Oct n)$.
\end{theorem}

\begin{theorem}[Suspension raises the co-index by at least one]
If $\Oct m \Cimp K$ holds, then $\Oct(m+1) \Cimp S(K)$ holds. In words,
$\coind(K) \ge m \Rightarrow \coind(S(K)) \ge m+1$.
\end{theorem}

\begin{proof}
Let $g : \Oct m \to K$ be equivariant simplicial. Then $S(g) : S(\Oct m) \to S(K)$ is
equivariant simplicial, and $\varphi_m : \Oct(m+1) \to S(\Oct m)$ too. The composite
$S(g)\circ\varphi_m : \Oct(m+1) \to S(K)$ is the required map.
\end{proof}

\begin{corollary}
$\Oct(n+1) \Cimp S(\Oct n)$ holds; the octahedral tower realizes the diagonal
$\coind(\Oct n) \ge n$, and suspension carries these certificates up the ladder in
lockstep.
\end{corollary}

\section{A combinatorial Borsuk--Ulam obstruction}

\begin{theorem}[Borsuk--Ulam, base case]
For $n \ge 1$ there is no $\Ztwo$-simplicial map $\Oct n \to \Oct 0$; equivalently any
such map forces $n = 0$, so $\coind(S^0) = \coind(\Oct 0) = 0$.
\end{theorem}

\begin{proof}
Suppose $n \ge 1$ and $g : \Oct n \to \Oct 0$ is $\Ztwo$-simplicial. The target has two
vertices, the single antipodal pair; its faces have at most one vertex. Take
$a = (0,+)$, $b = (1,+)$ on distinct axes; $\{a,b\}$ is a face, so $\{g(a),g(b)\}$ is a
face of $\Oct 0$, forcing $g(a) = g(b)$. Likewise $\{a,\alpha(b)\} = \{(0,+),(1,-)\}$ is
a face, so $\{g(a),g(\alpha(b))\}$ is a face; by equivariance $g(\alpha(b)) =
\alpha(g(b)) = \alpha(g(a))$. Then $\{g(a),\alpha(g(a))\}$ would be a face of $\Oct 0$
--- but it is the forbidden antipodal pair. Contradiction.
\end{proof}

\begin{remark}
Both freeness of $\alpha$ and antipodal-pair-freeness of faces are essential: dropping
either would legalize a constant map and falsify the theorem. This is the discrete
Borsuk--Ulam obstruction.
\end{remark}

\section{Discussion}

Theorem~6.5 gives the exact ``$+1$'' arithmetic of a single suspension, and
Theorem~7.1 shows the model detects the Borsuk--Ulam obstruction underlying
$\coind(S(K)) \le \dim(K)+1$. The gap to the full Sharp-Excess Conjecture is genuine: a
single suspension adds one apex axis and $\varphi_n$ spends it climbing one rung, so a
jump of size $d+1-c$ cannot come from the lone new coordinate. It must come from the
global equivariant connectivity of $K$: suspension repairs precisely the equivariant
homotopical defect suppressing $\coind(K)$, and that defect can be engineered to be as
large as the ambient dimension allows. Constructing such complexes for every feasible
$c$ is the open problem; the octahedral spheres supply the exact upper-bound
certificates.

\section{Applications and future work}

For a graph $G$, $\chi(G) \ge \coind(B(G)) + 2$, and Csorba's identity
$B_0(G) \simeq S(B(G))$ makes suspension excess a graph-theoretic quantity, promising
sharpened chromatic bounds. Future work: (1) prove the Sharp-Excess Conjecture for all
$1 \le c \le d$; (2) prove a full combinatorial Borsuk--Ulam, no equivariant simplicial
map $\Oct m \to \Oct n$ for $m > n$, giving $\coind(\Oct n) = n$ exactly via a discrete
degree/parity count; (3) relate the suspension excess of box complexes to strengthenings
of the Lov\'asz bound.

\section{Conclusion}

We built a compact, subdivision-free model of free $\Ztwo$-complexes and established the
constructive lower-bound half of the maximal-excess program --- functoriality of
suspension, the explicit map $\Oct(n+1) \to S(\Oct n)$, the co-index-raising inequality,
and the octahedral diagonal --- together with a genuine Borsuk--Ulam base case,
$\coind(S^0) = 0$. This provides a verified foundation for the deeper large-jump
construction demanded by the Sharp-Excess Conjecture.

\end{document}

