"""Demo: the octahedral sphere tower Oct(n) and its exact dimension."""
from itertools import combinations
from typing import List, Tuple

OctVertex = Tuple[int, int]  # (axis, sign in {+1,-1})

def oct_vertices(n: int) -> List[OctVertex]:
    return [(i, s) for i in range(n + 1) for s in (+1, -1)]

def is_oct_face(s: List[OctVertex]) -> bool:
    axes = [i for (i, _) in s]
    return len(axes) == len(set(axes))  # no antipodal pair

def oct_dimension(n: int) -> int:
    vs = oct_vertices(n)
    best = -1
    for k in range(len(vs) + 1):
        for combo in combinations(vs, k):
            if is_oct_face(list(combo)):
                best = max(best, len(combo) - 1)
    return best

if __name__ == "__main__":
    for n in range(5):
        top = [(i, +1) for i in range(n + 1)]
        print(f"Oct({n}): {2*(n+1)} vertices, dim={oct_dimension(n)}, "
              f"top face (positive orthant) size={len(top)}")

"""Demo: unreduced suspension S(K)=K*S^0 raises dimension by one."""
from itertools import combinations
from typing import Callable, List, Tuple

OctVertex = Tuple[int, int]

def oct_vertices(n: int) -> List[OctVertex]:
    return [(i, s) for i in range(n + 1) for s in (+1, -1)]

def is_oct_face(s) -> bool:
    axes = [i for (i, _) in s]
    return len(axes) == len(set(axes))

def dim(vertices, is_face: Callable) -> int:
    best = -1
    for k in range(len(vertices) + 1):
        for combo in combinations(vertices, k):
            if is_face(list(combo)):
                best = max(best, len(combo) - 1)
    return best

def suspend(vertices, is_face):
    N, S = ("apex", +1), ("apex", -1)
    new_v = [("base", v) for v in vertices] + [N, S]
    def new_face(s) -> bool:
        base = [x for (t, x) in s if t == "base"]
        if not is_face(base):
            return False
        return not (N in s and S in s)  # apexes never joined
    return new_v, new_face

if __name__ == "__main__":
    for n in range(4):
        v = oct_vertices(n)
        d0 = dim(v, is_oct_face)
        sv, sf = suspend(v, is_oct_face)
        print(f"dim Oct({n})={d0}  ->  dim S(Oct({n}))={dim(sv, sf)}")

"""Demo: exhaustive Borsuk-Ulam base case, no equivariant map Oct(n)->Oct(0)."""
from itertools import combinations, product
from typing import Callable, List, Tuple

OctVertex = Tuple[int, int]

def oct_vertices(n: int) -> List[OctVertex]:
    return [(i, s) for i in range(n + 1) for s in (+1, -1)]

def is_oct_face(s) -> bool:
    axes = [i for (i, _) in s]
    return len(axes) == len(set(axes))

def oct_alpha(v: OctVertex) -> OctVertex:
    i, s = v
    return (i, -s)

def faces(vertices):
    out = []
    for k in range(len(vertices) + 1):
        for combo in combinations(vertices, k):
            if is_oct_face(list(combo)):
                out.append(combo)
    return out

def exists_equivariant_simplicial(n: int) -> bool:
    src = oct_vertices(n)
    tgt = oct_vertices(0)
    src_faces = faces(src)
    for choice in product(tgt, repeat=n + 1):  # image of each '+' end
        def f(v: OctVertex, choice=choice) -> OctVertex:
            i, s = v
            img = choice[i]
            return img if s == +1 else oct_alpha(img)
        equi = all(f(oct_alpha(v)) == oct_alpha(f(v)) for v in src)
        simp = all(is_oct_face([f(v) for v in face]) for face in src_faces)
        if equi and simp:
            return True
    return False

if __name__ == "__main__":
    for n in range(4):
        ok = exists_equivariant_simplicial(n)
        print(f"Oct({n}) -> Oct(0): equivariant simplicial map "
              f"{'EXISTS' if ok else 'NONE (Borsuk-Ulam)'}")

