        ('base', v)  |-> ('base', g(v))
        ('apex', b)  |-> ('apex', b)      # apexes fixed
    return S_g  # : S(Oct m) -> S(K), equivariant + simplicial

function elevate_coindex(g : Oct(m) -> K):
    phi = connecting_map(m)               # Oct(m+1) -> S(Oct m)
    S_g = suspend_map(g)                  # S(Oct m) -> S(K)
    return compose(S_g, phi)              # Oct(m+1) -> S(K)
# certifies coind(S(K)) >= m + 1

