import matplotlib.pyplot as plt
import numpy as np
from itertools import combinations, product

def oct_vertices(n):
    return [(i, s) for i in range(n + 1) for s in (+1, -1)]

def is_face(s):
    axes = [i for (i, _) in s]
    return len(axes) == len(set(axes))

def alpha(v):
    i, s = v; return (i, -s)

def faces(vs):
    return [c for k in range(len(vs) + 1) for c in combinations(vs, k) if is_face(list(c))]

def has_map(n, k):
    src, tgt = oct_vertices(n), oct_vertices(k)
    sf = faces(src)
    for choice in product(tgt, repeat=n + 1):
        def f(v, choice=choice):
            i, s = v; img = choice[i]
            return img if s == +1 else alpha(img)
        if all(f(alpha(v)) == alpha(f(v)) for v in src) and \
           all(is_face([f(v) for v in fc]) for fc in sf):
            return True
    return False

N = 3
M = np.zeros((N + 1, N + 1))
for n in range(N + 1):
    for k in range(N + 1):
        M[n, k] = 1.0 if has_map(n, k) else 0.0

